package studio.jiayu.matrix;
import android.app.*;import android.widget.*;import android.content.pm.*;import java.security.*;
public final class MatrixSettings {
 public static void permissions(Activity a){
  if(android.os.Build.VERSION.SDK_INT>=33&&a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0){a.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},391);return;}
  android.os.PowerManager power=(android.os.PowerManager)a.getSystemService(android.content.Context.POWER_SERVICE);
  if(!power.isIgnoringBatteryOptimizations(a.getPackageName())){try{a.startActivity(new android.content.Intent(android.provider.Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,android.net.Uri.parse("package:"+a.getPackageName())));return;}catch(Exception ignored){a.startActivity(new android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+a.getPackageName())));return;}}
  new AlertDialog.Builder(a).setMessage("通知及 Android 后台授权已就绪。Neo 还需在“应用信息 → 耗电和后台 → 手动管理”中开启“允许后台运行”。只开启通知不能保证熄屏动画继续。").setPositiveButton("打开应用信息",(d,n)->a.startActivity(new android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+a.getPackageName())))).setNegativeButton("关闭",null).show();
 }
 public static void show(Activity a){if(MatrixDevice.available(a)){new AlertDialog.Builder(a).setTitle("Neo 原生背屏已就绪").setMessage("当前固件可直接驱动背屏，无需云端密钥。实播期间默认临时使用系统常亮，停止时恢复原显示模式。省电、温控与背屏总开关仍然有效。\n\n强行停止后，可再次打开此 App 恢复先前显示模式。一次只运行一个背屏播放器。").setPositiveButton("知道了",null).setNeutralButton("官方备用授权",(d,n)->showMcp(a)).show();return;}showMcp(a);}
 static void showMcp(Activity a){String identity=a.getPackageName();try{PackageInfo p=a.getPackageManager().getPackageInfo(a.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);byte[] bytes=p.signingInfo.getApkContentsSigners()[0].toByteArray();StringBuilder hex=new StringBuilder();for(byte b:MessageDigest.getInstance("MD5").digest(bytes))hex.append(String.format("%02x",b&255));identity+="\n签名 MD5："+hex;}catch(Exception ignored){}LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(40,12,40,12);TextView text=new TextView(a);text.setText("仅填写官方为当前包名和签名签发的设备能力凭据。模型 API Key 无效；其他 App 的凭据不可复用。\n\n"+identity+"\n\n"+(MatrixConnection.configured(a)?"已保存；留空保留":"未配置。当前可编辑、打包和后台模拟，背屏实播待授权。"));text.setTextIsSelectable(true);box.addView(text);EditText input=new EditText(a);input.setInputType(129);input.setHint("当前 App 的官方能力凭据");box.addView(input);new AlertDialog.Builder(a).setTitle("背屏连接").setView(box).setPositiveButton("保存",(d,n)->{String value=input.getText().toString().trim();if(!value.isEmpty())try{MatrixConnection.save(a,value);Toast.makeText(a,"已加密保存；启动播放时核验授权",0).show();}catch(Exception e){Toast.makeText(a,"保存失败",0).show();}}).setNeutralButton("移除授权",(d,n)->{try{MatrixConnection.save(a,"");}catch(Exception ignored){}}).setNegativeButton("关闭",null).show();}
}
